  FT["PH-H8730"] = {"id":"PH-H8730","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10277_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将高山省 Natonin 市镇 Sta. Isabel 描笼涯的 Natonin 国立中学附属校分离，改设为独立的 Sta. Isabel 国立中学，并为此拨款","en":"An Act Separating the Natonin National High School - Sta. Isabel Annex in Barangay Sta. Isabel, Municipality of Natonin, Mountain Province From the Natonin National High School, Converting It Into An Independent National High School to Be Known as Sta. Isabel National High School and Appropriating Funds Therefor","orig":"An Act Separating the Natonin National High School - Sta. Isabel Annex in Barangay Sta. Isabel, Municipality of Natonin, Mountain Province From the Natonin National High School, Converting It Into An Independent National High School to Be Known as Sta. Isabel National High School and Appropriating Funds Therefor","vi":"Đạo luật tách Phân hiệu Sta. Isabel của Trường Trung học Natonin Quốc gia tại Barangay Sta. Isabel, Đô thị Natonin, Tỉnh Mountain Province khỏi Trường Trung học Natonin Quốc gia và chuyển thành Trường Trung học Độc lập Quốc gia với tên gọi Trường Trung học Sta. Isabel Quốc gia, và bố trí kinh phí","th":"พระราชบัญญัติแยกวิทยาเขต Sta. Isabel ของโรงเรียนมัธยมศึกษา Natonin แห่งชาติในบารังไกย์ Sta. Isabel เทศบาล Natonin จังหวัด Mountain Province ออกจากโรงเรียนมัธยมศึกษา Natonin แห่งชาติและยกฐานะเป็นโรงเรียนมัธยมศึกษาเอกเทศแห่งชาติชื่อโรงเรียนมัธยมศึกษา Sta. Isabel แห่งชาติ และจัดสรรงบประมาณ","id":"Undang-Undang Memisahkan Kampus Sta. Isabel, Sekolah Menengah Natonin Nasional di Barangay Sta. Isabel, Kotamadya Natonin, Provinsi Mountain Province dari Sekolah Menengah Natonin Nasional dan menjadi Sekolah Menengah Mandiri Nasional dengan nama Sekolah Menengah Sta. Isabel Nasional, dan mengalokasikan dana","ms":"Akta Memisahkan Kampus Sta. Isabel, Sekolah Menengah Natonin Kebangsaan di Barangay Sta. Isabel, Perbandaran Natonin, Wilayah Mountain Province daripada Sekolah Menengah Natonin Kebangsaan dan menjadi Sekolah Menengah Bebas Kebangsaan dengan nama Sekolah Menengah Sta. Isabel Kebangsaan, dan memperuntukkan dana"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10277","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10277_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8730-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. – The Natonin National High School – Sta. Isabel Annex in Barangay Sta. Isabel, Municipality of Natonin, Mountain Province is hereby separated from the Natonin National High School and converted into an independent national high school to be known as Sta. Isabel National High School."}},{"id":"PH-H8730-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel, assets, liabilities and records of the Natonin National High School – Sta. Isabel Annex are hereby transferred to and absorbed by the Sta. Isabel National High School."}},{"id":"PH-H8730-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Sta. Isabel National High School, the initial funding of which shall be charged against the current year’s appropriations of the Natonin National High School – Sta. Isabel Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8730-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8730-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Natonin National High School - Sta. Isabel Annex in Barangay Sta. Isabel, Municipality of Natonin, Mountain Province From the Natonin National High School, Converting It Into An Independent National High School to Be Known as Sta. Isabel National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
