  FT["PH-H8765"] = {"id":"PH-H8765","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10312_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Bauang市","en":"An Act Converting the Acao National High School in Barangay Acao, Municipality of Bauang, Province of La Union Into a National Vocatiqnal High School to Be Known as Eulogio Clarence De Guzman Junior Memorial National Vocational High School and Appropriating Funds Therefor","orig":"An Act Converting the Acao National High School in Barangay Acao, Municipality of Bauang, Province of La Union Into a National Vocatiqnal High School to Be Known as Eulogio Clarence De Guzman Junior Memorial National Vocational High School and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Acao National High School thành Eulogio Clarence De Guzman Junior Memorial National Vocational High School","th":"พระราชบัญญัติเปลี่ยนสถานะ Acao National High School เป็น Eulogio Clarence De Guzman Junior Memorial National Vocational High School","id":"Undang-Undang mengubah Acao National High School menjadi Eulogio Clarence De Guzman Junior Memorial National Vocational High School","ms":"Akta menukar Acao National High School kepada Eulogio Clarence De Guzman Junior Memorial National Vocational High School"},"level":"law","status":"active","topics":["labor","administrative","education"],"docNumber":"Republic Act No. 10312","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10312_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8765-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion into a National Vocational High School. - The Acao National High School in Barangay Acao, Municipality of Bauang, Province of La Union is hereby converted into a national vocational high school to be known as Eulogio Clarence De Guzman Junior Memorial National Vocational High School."}},{"id":"PH-H8765-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Acao National High School are hereby transferred to and absorbed by the Eulogio Clarence De Guzman Junior Memorial National Vocational High School."}},{"id":"PH-H8765-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of the Eulogio Clarence De Guzman Junior Memorial National Vocational High School, the initial funding of which shall be charged against the current year's appropriation of the Acao National High School. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8765-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8765-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124"};
